/*
 * A045349  Primes congruent to {0, 1, 2} mod 5.
 * https://oeis.org/A045349
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 28, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   isPrimeTrial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence of primes ≡ 0, 1, 2 (mod 5) – generated by successive search.
   a(1) = 2, a(2) = 5, a(3) = 7, a(4) = 11, … */

#include <stdlib.h>
#include <stdbool.h>

#include "../utils/isPrimeTrial.h"

static seq_t *cache = NULL;     /* array of primes in the sequence */
static size_t  cap   = 0;       /* current allocation size */
static size_t  sz    = 0;       /* number of primes stored */

static void grow_cache(void)
{
    const size_t new_cap = (cap == 0) ? 16 : cap << 1;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) abort();           /* allocation failed */
    cache = tmp;
    cap   = new_cap;
}

seq_t a(idx_t n)
{
    if (n < 1) return (seq_t)0;   /* undefined for n == 0, harmless */

    /* extend the cache until it contains at least n primes */
    while (sz < (size_t)n) {
        seq_t cand = (seq_t)(sz == 0 ? 2 : cache[sz-1] + 1);

        for (;;) {
            if (isPrimeTrial(cand)) {
                seq_t r = cand % (seq_t)5;
                if (r == (seq_t)0 || r == (seq_t)1 || r == (seq_t)2) {
                    if (sz == cap) grow_cache();
                    cache[sz++] = cand;
                    break;                      /* found next needed prime */
                }
            }
            cand++;   /* try next integer */
        }
    }

    return cache[n-1];
}
